actions.script:
// Adds the states missing from gladiknow.com's removal form state select.
// The select offers 19 states, but /api/optout/find returns records for any
// state, so without this fillForm fails with "could not find matching value
// for select element" for users everywhere else.
//
// Called as function (userProfile, root). The select is React-controlled and
// its onChange reads event.target.value, so an added option is enough for
// fillForm's change event to put the state into the search request.

const STATES = {
  AL: "Alabama", AK: "Alaska", AZ: "Arizona", AR: "Arkansas", CA: "California",
  CO: "Colorado", CT: "Connecticut", DE: "Delaware", DC: "District Of Columbia",
  FL: "Florida", GA: "Georgia", HI: "Hawaii", ID: "Idaho", IL: "Illinois",
  IN: "Indiana", IA: "Iowa", KS: "Kansas", KY: "Kentucky", LA: "Louisiana",
  ME: "Maine", MD: "Maryland", MA: "Massachusetts", MI: "Michigan",
  MN: "Minnesota", MS: "Mississippi", MO: "Missouri", MT: "Montana",
  NE: "Nebraska", NV: "Nevada", NH: "New Hampshire", NJ: "New Jersey",
  NM: "New Mexico", NY: "New York", NC: "North Carolina", ND: "North Dakota",
  OH: "Ohio", OK: "Oklahoma", OR: "Oregon", PA: "Pennsylvania",
  RI: "Rhode Island", SC: "South Carolina", SD: "South Dakota",
  TN: "Tennessee", TX: "Texas", UT: "Utah", VT: "Vermont", VA: "Virginia",
  WA: "Washington", WV: "West Virginia", WI: "Wisconsin", WY: "Wyoming",
};

// The removal form is the one with the success-styled submit button. The
// header search form on the same page also has a select#state.
function removalStateSelect() {
  for (const form of root.querySelectorAll("form")) {
    if (form.querySelector("button.success")) {
      return form.querySelector("select#state");
    }
  }
  return null;
}

const select = removalStateSelect();
if (!select) throw new Error("removal form state select not found");

const present = new Set([...select.options].map((option) => option.value));
for (const [code, name] of Object.entries(STATES)) {
  if (present.has(code)) continue;
  const option = root.createElement("option");
  option.value = code;
  option.textContent = name;
  select.appendChild(option);
}

// Adds the states missing from gladiknow.com's removal form state select.
// The select offers 19 states, but /api/optout/find returns records for any
// state, so without this fillForm fails with "could not find matching value
// for select element" for users everywhere else.
//
// Called as function (userProfile, root). The select is React-controlled and
// its onChange reads event.target.value, so an added option is enough for
// fillForm's change event to put the state into the search request.

const STATES = {
  AL: "Alabama", AK: "Alaska", AZ: "Arizona", AR: "Arkansas", CA: "California",
  CO: "Colorado", CT: "Connecticut", DE: "Delaware", DC: "District Of Columbia",
  FL: "Florida", GA: "Georgia", HI: "Hawaii", ID: "Idaho", IL: "Illinois",
  IN: "Indiana", IA: "Iowa", KS: "Kansas", KY: "Kentucky", LA: "Louisiana",
  ME: "Maine", MD: "Maryland", MA: "Massachusetts", MI: "Michigan",
  MN: "Minnesota", MS: "Mississippi", MO: "Missouri", MT: "Montana",
  NE: "Nebraska", NV: "Nevada", NH: "New Hampshire", NJ: "New Jersey",
  NM: "New Mexico", NY: "New York", NC: "North Carolina", ND: "North Dakota",
  OH: "Ohio", OK: "Oklahoma", OR: "Oregon", PA: "Pennsylvania",
  RI: "Rhode Island", SC: "South Carolina", SD: "South Dakota",
  TN: "Tennessee", TX: "Texas", UT: "Utah", VT: "Vermont", VA: "Virginia",
  WA: "Washington", WV: "West Virginia", WI: "Wisconsin", WY: "Wyoming",
};

// The removal form is the one with the success-styled submit button. The
// header search form on the same page also has a select#state.
function removalStateSelect() {
  for (const form of root.querySelectorAll("form")) {
    if (form.querySelector("button.success")) {
      return form.querySelector("select#state");
    }
  }
  return null;
}

const select = removalStateSelect();
if (!select) throw new Error("removal form state select not found");

const present = new Set([...select.options].map((option) => option.value));
for (const [code, name] of Object.entries(STATES)) {
  if (present.has(code)) continue;
  const option = root.createElement("option");
  option.value = code;
  option.textContent = name;
  select.appendChild(option);
