// Marks the gladiknow.com result row this opt-out job is for, so the next
// click removes that record and not the first namesake on the page.
//
// Called as function (userProfile, root) with dataSource: extractedProfile,
// so userProfile is the matched profile. The page shows only name and
// "street, city, ST" per row, so the scan stores the location text as the
// profileUrl to give every row its own identifier. Newer C-S-S builds resolve
// that text against the page URL; older builds keep it as raw text. Accept
// both.

const MARK = "data-pir-target";

function normalize(text) {
  return (text || "").replace(/\s+/g, " ").trim().toLowerCase();
}

// The two forms the scan can have stored for a row's location text. The scan
// reads innerText, which collapses the double spaces the page renders, so
// collapse them here before resolving.
function storedForms(locationText) {
  const raw = locationText.replace(/\s+/g, " ").trim();
  const forms = [normalize(raw)];
  try {
    forms.push(normalize(new URL(raw, root.location.href).href));
  } catch (e) {
    // Text that is not resolvable as a URL can only have been stored raw.
  }
  return forms;
}

const target = normalize(userProfile && userProfile.profileUrl);
if (!target) throw new Error("extracted profile has no profileUrl");

const rows = [...root.querySelectorAll(".optout-record-item")];
const matches = rows.filter((row) => {
  const location = row.querySelector(".optout-record-location");
  return location && storedForms(location.textContent).includes(target);
});

// Clicking a guess would remove someone else's record, so fail instead.
if (matches.length === 0) throw new Error("no result row matches the extracted profile");

matches[0].setAttribute(MARK, "true");
